const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');

const body = input?.body || {};
const data = body?.data || {};
const key = data?.key || {};
const message = data?.message || {};
const remoteJid = String(key?.remoteJid || '');
const fromMe = key?.fromMe === true;
const messageId = String(key?.id || data?.messageId || '');

// Mesaj olmayan, grup, status ve broadcast olaylarını yut.
if (
  !remoteJid ||
  remoteJid.endsWith('@g.us') ||
  remoteJid === 'status@broadcast' ||
  remoteJid.includes('@broadcast') ||
  !data?.message
) {
  return [{ json: { _route: 'ignore', reason: 'invalid_or_unsupported_event' } }];
}

// Tekrarlanan webhook olaylarını engelle.
if (!staticData._seenMessageIds) staticData._seenMessageIds = {};
const now = Date.now();
const seenTtlMs = 6 * 60 * 60 * 1000;

for (const [id, seenAt] of Object.entries(staticData._seenMessageIds)) {
  if (now - Number(seenAt || 0) > seenTtlMs) {
    delete staticData._seenMessageIds[id];
  }
}

if (messageId && staticData._seenMessageIds[messageId]) {
  return [{ json: { _route: 'ignore', reason: 'duplicate_message', messageId } }];
}

if (messageId) {
  staticData._seenMessageIds[messageId] = now;

  const ids = Object.keys(staticData._seenMessageIds);
  if (ids.length > 3000) {
    ids
      .sort((a, b) => staticData._seenMessageIds[a] - staticData._seenMessageIds[b])
      .slice(0, ids.length - 2500)
      .forEach((id) => delete staticData._seenMessageIds[id]);
  }
}

const senderNumber = remoteJid
  .replace('@s.whatsapp.net', '')
  .replace('@g.us', '')
  .replace('@lid', '');

const senderName = String(data?.pushName || senderNumber || 'Bilinmeyen müşteri');

let messageText = String(
  message?.conversation ||
  message?.extendedTextMessage?.text ||
  message?.imageMessage?.caption ||
  message?.videoMessage?.caption ||
  message?.documentMessage?.caption ||
  message?.buttonsResponseMessage?.selectedDisplayText ||
  message?.buttonsResponseMessage?.selectedButtonId ||
  message?.listResponseMessage?.title ||
  message?.listResponseMessage?.singleSelectReply?.selectedRowId ||
  message?.templateButtonReplyMessage?.selectedDisplayText ||
  message?.templateButtonReplyMessage?.selectedId ||
  ''
).trim();

let messageType = 'text';

if (!messageText) {
  if (message?.imageMessage) {
    messageType = 'image';
    messageText = '[Müşteri açıklamasız bir görsel gönderdi]';
  } else if (message?.videoMessage) {
    messageType = 'video';
    messageText = '[Müşteri açıklamasız bir video gönderdi]';
  } else if (message?.audioMessage) {
    messageType = 'audio';
    messageText = '[Müşteri bir ses kaydı gönderdi]';
  } else if (message?.documentMessage) {
    messageType = 'document';
    const fileName = message.documentMessage.fileName || '';
    messageText = fileName
      ? `[Müşteri belge gönderdi: ${fileName}]`
      : '[Müşteri bir belge gönderdi]';
  } else if (message?.locationMessage) {
    messageType = 'location';
    messageText = '[Müşteri konum gönderdi]';
  } else if (message?.contactMessage || message?.contactsArrayMessage) {
    messageType = 'contact';
    messageText = '[Müşteri kişi/kartvizit gönderdi]';
  } else if (message?.stickerMessage) {
    messageType = 'sticker';
    messageText = '[Müşteri sticker gönderdi]';
  } else {
    return [{ json: { _route: 'ignore', reason: 'empty_or_unsupported_message', messageId } }];
  }
}

const normalized = messageText.trim();

if (fromMe && (normalized === '++' || normalized === '--')) {
  return [{
    json: {
      _route: 'command',
      _command: normalized === '++' ? 'pause' : 'resume',
      senderNumber,
      senderName,
      messageText: normalized,
      messageId,
      fromMe: true
    }
  }];
}

// Bizim gönderdiğimiz normal mesajları yeniden işleme.
if (fromMe) {
  return [{ json: { _route: 'ignore', reason: 'outgoing_non_command', messageId } }];
}

return [{
  json: {
    _route: 'batch',
    senderNumber,
    senderName,
    messageText,
    messageType,
    messageId,
    receivedAt: now,
    fromMe: false
  }
}];

const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

const senderNumber = String(input.senderNumber || '');
const senderName = String(input.senderName || senderNumber || 'Bilinmeyen müşteri');
const messageText = String(input.messageText || '').trim();
const messageId = String(input.messageId || '');
const messageType = String(input.messageType || 'text');
const now = Number(input.receivedAt || Date.now());
const maxPendingMessages = 30;

if (!senderNumber || !messageText) {
  return [{ json: { _action: 'ignore', reason: 'missing_sender_or_message' } }];
}

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};
if (!staticData._lastReply) staticData._lastReply = {};

// Müşteri yeni mesaj yazdıysa önceki "cevap bekleniyor" alarmını kaldır.
delete staticData._lastReply[senderNumber];

if (staticData._manualModes[senderNumber] === true) {
  return [{
    json: {
      _action: 'manual_mode',
      senderNumber,
      senderName
    }
  }];
}

if (!staticData._batches[senderNumber]) {
  staticData._batches[senderNumber] = {
    pendingMessages: [],
    processingMessages: [],
    startTime: now,
    lastMessageTime: now,
    senderName,
    processing: false,
    processingStartedAt: null,
    processingToken: null
  };
}

const batch = staticData._batches[senderNumber];

// Eski workflow veri yapısından güvenli geçiş.
if (!Array.isArray(batch.pendingMessages)) {
  batch.pendingMessages = Array.isArray(batch.messages) ? batch.messages : [];
}
if (!Array.isArray(batch.processingMessages)) {
  batch.processingMessages = [];
}
delete batch.messages;

if (batch.pendingMessages.length >= maxPendingMessages) {
  return [{
    json: {
      _action: 'spam_limit',
      senderNumber,
      senderName,
      messageCount: batch.pendingMessages.length
    }
  }];
}

batch.pendingMessages.push({
  id: messageId,
  text: messageText,
  type: messageType,
  timestamp: now,
  time: new Date(now).toLocaleTimeString('tr-TR', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Europe/Istanbul'
  })
});

batch.lastMessageTime = now;
batch.senderName = senderName;

return [{
  json: {
    _action: batch.processing ? 'queued_during_processing' : 'queued',
    senderNumber,
    senderName,
    pendingCount: batch.pendingMessages.length,
    processing: batch.processing === true
  }
}];

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData._manualModes) staticData._manualModes = {};
if (!staticData._batches) staticData._batches = {};
if (!staticData._lastReply) staticData._lastReply = {};

const num = String(input.senderNumber || '');
const name = String(input.senderName || num || 'Bilinmeyen müşteri');
const command = input._command;

if (!num) {
  return [{ json: { _action: 'ignore', reason: 'missing_customer_number' } }];
}

if (command === 'pause') {
  staticData._manualModes[num] = true;
  delete staticData._batches[num];
  delete staticData._lastReply[num];

  return [{
    json: {
      bildirim:
        'MANUEL MOD AKTİF\n' +
        'Müşteri: ' + name + ' (' + num + ')\n' +
        'Otomatik cevap durduruldu.\n' +
        'Tekrar otomatik moda geçmek için müşteri sohbetinde -- yazın.',
      senderNumber: num,
      senderName: name,
      action: 'command_pause',
      notifyAdmins: true
    }
  }];
}

if (command === 'resume') {
  delete staticData._manualModes[num];
  if (!staticData._unclearCounts) staticData._unclearCounts = {};
  delete staticData._unclearCounts[num];
  delete staticData._lastReply[num];

  return [{
    json: {
      bildirim:
        'OTOMATİK MOD AKTİF\n' +
        'Müşteri: ' + name + ' (' + num + ')\n' +
        'Bu müşteriye otomatik cevap yeniden açıldı.',
      senderNumber: num,
      senderName: name,
      action: 'command_resume',
      notifyAdmins: true
    }
  }];
}

return [{
  json: {
    _action: 'ignore',
    reason: 'unknown_command'
  }
}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();

const windowMs = 3 * 60 * 1000;
const processingTimeoutMs = 2 * 60 * 1000;

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};

const ready = [];

for (const [number, rawBatch] of Object.entries(staticData._batches)) {
  const batch = rawBatch || {};

  // Eski veri yapısından geçiş.
  if (!Array.isArray(batch.pendingMessages)) {
    batch.pendingMessages = Array.isArray(batch.messages) ? batch.messages : [];
  }
  if (!Array.isArray(batch.processingMessages)) {
    batch.processingMessages = [];
  }
  delete batch.messages;

  if (staticData._manualModes[number] === true) {
    delete staticData._batches[number];
    continue;
  }

  // Yarım kalan AI işlemini yeniden kuyruğa al.
  if (
    batch.processing === true &&
    batch.processingStartedAt &&
    now - Number(batch.processingStartedAt) > processingTimeoutMs
  ) {
    batch.pendingMessages = [
      ...batch.processingMessages,
      ...batch.pendingMessages
    ];
    batch.processingMessages = [];
    batch.processing = false;
    batch.processingStartedAt = null;
    batch.processingToken = null;
  }

  if (batch.processing === true) continue;
  if (!batch.pendingMessages.length) {
    delete staticData._batches[number];
    continue;
  }

  const lastTime = Number(batch.lastMessageTime || batch.startTime || now);
  const idleTime = now - lastTime;

  if (idleTime >= windowMs) {
    ready.push({
      number,
      lastTime,
      batch
    });
  }
}

// Aynı execution'da yalnızca bir müşteriyi işle.
// Böylece AI memory ve $input.first() müşterileri birbirine karıştırmaz.
ready.sort((a, b) => a.lastTime - b.lastTime);
const selected = ready[0];

if (!selected) {
  return [{ json: { senderNumber: '', messageCount: 0, _ready: false } }];
}

const { number, batch } = selected;
const processingMessages = batch.pendingMessages.splice(0);
const processingToken =
  number + '-' + now + '-' + Math.random().toString(36).slice(2, 10);

batch.processingMessages = processingMessages;
batch.processing = true;
batch.processingStartedAt = now;
batch.processingToken = processingToken;

const allMessagesText = processingMessages
  .map((message, index) => {
    const typeLabel = message.type && message.type !== 'text'
      ? ` (${message.type})`
      : '';
    return `${index + 1}. [${message.time || ''}]${typeLabel} ${message.text}`;
  })
  .join('\n');

return [{
  json: {
    _ready: true,
    senderNumber: number,
    senderName: batch.senderName || number,
    messageCount: processingMessages.length,
    allMessagesText,
    batchToken: processingToken
  }
}];

const input = $input.first().json;

return [{
  json: {
    senderNumber: input.senderNumber,
    senderName: input.senderName,
    allMessagesText: input.allMessagesText,
    messageCount: input.messageCount,
    batchToken: input.batchToken,
    _prompt:
      'Müşteri adı: ' + input.senderName +
      '\nBu batch içindeki mesaj sayısı: ' + input.messageCount +
      '\n\nYeni müşteri mesajları:\n' + input.allMessagesText
  }
}];

const staticData = $getWorkflowStaticData('global');
const aiOutput = String($input.first().json?.output || '');

const context = $('Store Context').item.json;
const senderNumber = String(context.senderNumber || '');
const senderName = String(context.senderName || senderNumber || 'Bilinmeyen müşteri');
const allMessagesText = String(context.allMessagesText || '');
const batchToken = String(context.batchToken || '');

if (!staticData._unclearCounts) staticData._unclearCounts = {};
if (!staticData._batches) staticData._batches = {};

const batch = staticData._batches[senderNumber];
const validClaim = Boolean(
  batch &&
  batch.processing === true &&
  batch.processingToken === batchToken
);

if (!validClaim) {
  return [{
    json: {
      senderNumber,
      senderName,
      batchToken,
      action: 'ignore',
      intent: 'other',
      summary: 'Geçersiz veya süresi dolmuş AI işlemi yutuldu',
      reply: '',
      missingFields: [],
      confidence: 0,
      handoffReason: '',
      expectsReply: false,
      notifyAdmins: false,
      validClaim: false,
      bildirim: ''
    }
  }];
}

let parsed = null;
let parseError = '';

try {
  const cleaned = aiOutput
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  parsed = JSON.parse(cleaned);
} catch (firstError) {
  try {
    const match = aiOutput.match(/\{[\s\S]*\}/);
    if (!match) throw firstError;
    parsed = JSON.parse(match[0]);
  } catch (secondError) {
    parseError = String(secondError?.message || secondError || 'Bilinmeyen ayrıştırma hatası');
  }
}

const allowedActions = new Set(['reply', 'handoff', 'ignore']);
const allowedIntents = new Set([
  'product_compatibility',
  'price_stock',
  'order_status',
  'shipping',
  'return_complaint',
  'wholesale',
  'greeting',
  'unclear',
  'other'
]);

let action = allowedActions.has(parsed?.action) ? parsed.action : 'handoff';
let intent = allowedIntents.has(parsed?.intent) ? parsed.intent : 'other';
let summary = String(parsed?.summary || '').trim();
let reply = String(parsed?.reply || '').trim();
let missingFields = Array.isArray(parsed?.missingFields)
  ? parsed.missingFields.map((value) => String(value)).slice(0, 10)
  : [];
let confidence = Number(parsed?.confidence);
let handoffReason = String(parsed?.handoffReason || '').trim();
let expectsReply = parsed?.expectsReply === true;

if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

if (parseError) {
  action = 'handoff';
  intent = 'other';
  summary = 'AI çıktısı ayrıştırılamadı; manuel kontrol gerekiyor';
  reply = 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
  missingFields = [];
  confidence = 0;
  handoffReason = 'AI JSON ayrıştırma hatası: ' + parseError.slice(0, 120);
  expectsReply = false;
}

// Belirsiz talep sayacını deterministik yönet.
if (intent === 'unclear') {
  staticData._unclearCounts[senderNumber] =
    Number(staticData._unclearCounts[senderNumber] || 0) + 1;

  if (staticData._unclearCounts[senderNumber] >= 2) {
    action = 'handoff';
    reply = 'Talebinizi doğru yönlendirebilmek için ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
    handoffReason = handoffReason || 'Talep iki kez anlaşılmadı';
    expectsReply = false;
  }
} else {
  delete staticData._unclearCounts[senderNumber];
}

// Düşük güvenli, belirsiz olmayan işlemleri insana aktar.
if (
  confidence < 0.55 &&
  intent !== 'unclear' &&
  intent !== 'greeting' &&
  action !== 'ignore'
) {
  action = 'handoff';
  reply = reply || 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
  handoffReason = handoffReason || 'Düşük AI güven skoru';
  expectsReply = false;
}

if (action === 'reply' && !reply) {
  action = 'handoff';
  reply = 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
  handoffReason = handoffReason || 'Boş otomatik cevap';
  expectsReply = false;
}

if (action === 'handoff') {
  reply = reply || 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
  expectsReply = false;
}

if (action === 'ignore') {
  reply = '';
  expectsReply = false;
}

if (!summary) {
  summary = allMessagesText
    .replace(/\s+/g, ' ')
    .slice(0, 160) || 'Müşteri mesajı';
}

const intentLabels = {
  product_compatibility: 'Ürün/Uyumluluk',
  price_stock: 'Fiyat/Stok',
  order_status: 'Sipariş Durumu',
  shipping: 'Kargo',
  return_complaint: 'Şikâyet/İade',
  wholesale: 'Toptan/Bayi',
  greeting: 'Selamlama',
  unclear: 'Belirsiz Talep',
  other: 'Diğer'
};

const statusLabel =
  action === 'handoff'
    ? 'MANUEL MÜDAHALE GEREKİYOR'
    : action === 'reply'
      ? 'OTOMATİK CEVAP HAZIR'
      : 'CEVAP GEREKMİYOR';

let bildirim =
  'YENİ MESAJ - filtreoto.com\n' +
  'Gönderen: ' + senderName + '\n' +
  'Numara: ' + senderNumber + '\n' +
  'Konu: ' + (intentLabels[intent] || intent) + '\n' +
  'Güven: %' + Math.round(confidence * 100) + '\n' +
  'Durum: ' + statusLabel + '\n' +
  'Özet: ' + summary;

if (missingFields.length) {
  bildirim += '\nEksik bilgi: ' + missingFields.join(', ');
}

if (handoffReason) {
  bildirim += '\nAktarım nedeni: ' + handoffReason;
}

if (action === 'reply') {
  bildirim += '\n\nMüşteriye gönderilen yanıt:\n' + reply;
} else if (action === 'handoff') {
  bildirim += '\n\nMüşteriye gönderilecek aktarım mesajı:\n' + reply;
}

return [{
  json: {
    senderNumber,
    senderName,
    batchToken,
    action,
    intent,
    summary,
    reply,
    missingFields,
    confidence,
    handoffReason,
    expectsReply,
    validClaim: true,
    notifyAdmins: action === 'reply' || action === 'handoff',
    bildirim
  }
}];

const staticData = $getWorkflowStaticData('global');
const context = $('Parse AI Output').item.json;

const senderNumber = String(context.senderNumber || '');
const batchToken = String(context.batchToken || '');

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};
if (!staticData._lastReply) staticData._lastReply = {};

const batch = staticData._batches[senderNumber];
const validClaim = Boolean(
  context.validClaim === true &&
  batch &&
  batch.processing === true &&
  batch.processingToken === batchToken
);

if (!validClaim) {
  return [{
    json: {
      ...context,
      notifyAdmins: false,
      needsHandoffAck: false,
      finalized: false
    }
  }];
}

if (context.action === 'handoff') {
  staticData._manualModes[senderNumber] = true;
  delete staticData._batches[senderNumber];
    delete staticData._unclearCounts[senderNumber];
  delete staticData._lastReply[senderNumber];
} else {
  batch.processingMessages = [];
  batch.processing = false;
  batch.processingStartedAt = null;
  batch.processingToken = null;

  if (!Array.isArray(batch.pendingMessages)) {
    batch.pendingMessages = [];
  }

  if (batch.pendingMessages.length === 0) {
    delete staticData._batches[senderNumber];
    delete staticData._unclearCounts[senderNumber];
  }

  if (context.action === 'reply' && context.expectsReply === true) {
    staticData._lastReply[senderNumber] = {
      time: Date.now(),
      senderName: context.senderName,
      intent: context.intent,
      summary: context.summary
    };
  } else {
    delete staticData._lastReply[senderNumber];
  }
}

return [{
  json: {
    ...context,
    finalized: true,
    needsHandoffAck:
      context.action === 'handoff' &&
      Boolean(String(context.reply || '').trim())
  }
}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const idleAlertMs = 10 * 60 * 1000;

if (!staticData._lastReply) staticData._lastReply = {};
if (!staticData._manualModes) staticData._manualModes = {};

const alerts = [];

for (const [number, rawRecord] of Object.entries(staticData._lastReply)) {
  if (staticData._manualModes[number] === true) {
    delete staticData._lastReply[number];
    continue;
  }

  const record =
    typeof rawRecord === 'number'
      ? { time: rawRecord }
      : (rawRecord || {});

  const lastReplyTime = Number(record.time || 0);

  if (!lastReplyTime) {
    delete staticData._lastReply[number];
    continue;
  }

  if (now - lastReplyTime >= idleAlertMs) {
    const senderName = String(record.senderName || number);
    const summary = String(record.summary || '').trim();

    alerts.push({
      json: {
        senderNumber: number,
        bildirim:
          'CEVAP BEKLENEN MÜŞTERİ\n' +
          'Müşteri: ' + senderName + ' (' + number + ')\n' +
          (summary ? 'Son talep: ' + summary + '\n' : '') +
          'Botun son sorusundan sonra 10 dakikadır yeni mesaj gelmedi.',
        _idleAlert: true
      }
    });

    delete staticData._lastReply[number];
  }
}

if (!alerts.length) {
  return [{ json: { _idleAlert: false } }];
}

return alerts;
